appendCss:
/* R4: local information and navigation; R3 hero/logo rules above remain intact. */
.matrix-supplements .ms-breadcrumb{font:13px/1.7 Arial,sans-serif;color:#eef5f1;margin:0 auto 22px;text-wrap:balance}
.matrix-supplements .ms-breadcrumb a{display:inline-block;padding:8px 3px;text-underline-offset:4px}
.matrix-supplements .ms-hero-note{font-size:14px;line-height:1.7;color:#edf5f1;margin:16px auto 0;max-width:680px}
.matrix-supplements .ms-local-grid{display:grid;grid-template-columns:1.25fr 1fr;gap:40px;margin-top:32px;align-items:start}
.matrix-supplements .ms-location-card{background:var(--aqua);border:1px solid #c1d5cd;padding:28px}
.matrix-supplements .ms-location-card h3{margin-bottom:22px}
.matrix-supplements .ms-facts{margin:0;font-size:15px}
.matrix-supplements .ms-facts dt{font-weight:700;margin:18px 0 4px}
.matrix-supplements .ms-facts dd{margin:0}
.matrix-supplements .ms-area-links{display:flex;flex-wrap:wrap;gap:12px 24px;border-top:1px solid #c8d7cf;margin-top:32px;padding-top:20px;font-size:14px}
.matrix-supplements .ms-area-links a{display:inline-flex;align-items:center;min-height:44px;text-underline-offset:4px}
@media(max-width:720px){.matrix-supplements .ms-local-grid{grid-template-columns:1fr;gap:26px}.matrix-supplements .ms-location-card{padding:24px}}
